settings.custom_liquid:
{% comment %} Contractor Contact Info {% endcomment %}
{% assign mf = product.metafields.custom %}
{% if mf.email != blank or mf.mobile != blank or mf.address != blank %}
  <div class="contractor-info" style="
    font-family: 'Instrument Sans', sans-serif;
    font-size: 0.78rem;
    line-height: 1.5;
    margin-top: 0.5rem;
    color: #2d7a3a;
  ">
    {% if mf.email != blank %}
      <div><span style="font-weight: 600;">Email:</span> {{ mf.email }}</div>
    {% endif %}
    {% if mf.mobile != blank %}
      <div><span style="font-weight: 600;">Mobile:</span> {{ mf.mobile }}</div>
    {% endif %}
    {% if mf.city != blank or mf.state != blank %}
      <div><span style="font-weight: 600;">Location:</span>
        {% if mf.city != blank %}{{ mf.city }}{% endif %}{% if mf.city != blank and mf.state != blank %}, {% endif %}{% if mf.state != blank %}{{ mf.state }}{% endif %}
      </div>
    {% endif %}
    {% if mf.address != blank %}
      <div><span style="font-weight: 600;">Address:</span> {{ mf.address }}</div>
    {% endif %}
  </div>
{% endif %}
